/* @autogenerated */
package net.civeira.phylax.common.value.validation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

@DisplayName("ConstraintFailList add overloads")
class ConstraintFailListAddUnitTest {

  @Test
  @DisplayName("Should add a fail from code, field and wrong value")
  void shouldAddFailFromCodeFieldAndValue() {
    // Arrange — an empty list
    ConstraintFailList list = new ConstraintFailList();

    // Act — add a fail by its parts
    list.add("required", "name", null);

    // Assert — the fail is stored with its code
    List<? extends AbstractFail> fails = list.getFails().toList();
    assertEquals(1, fails.size());
    assertEquals("required", fails.get(0).getCode());
    assertTrue(fails.get(0) instanceof ConstraintFail);
  }

  @Test
  @DisplayName("Should add a fail from code, field, wrong value and message")
  void shouldAddFailWithMessage() {
    // Arrange — an empty list
    ConstraintFailList list = new ConstraintFailList();

    // Act — add a fail by its parts including a custom message
    list.add("format", "email", "bad", "Invalid email");

    // Assert — the fail is stored with its code
    List<? extends AbstractFail> fails = list.getFails().toList();
    assertEquals(1, fails.size());
    assertEquals("format", fails.get(0).getCode());
    assertTrue(list.includeCode("format"));
  }
}
